baseline_handler:
onOpenChange={(nextOpen) => {
        // Only an in-flight request blocks dismissal. Previously any `disabled`
        // state (e.g. an unmet precondition) also locked the dialog shut, so a
        // staff member could be stuck in a modal they could not cancel.
        if (isPending && !nextOpen) return;
        onOpenChange(nextOpen);
      }}

onClick={() =>
              setPending({
                input: {
                  scope,
                  action,
                  items: ready.map((p) => ({
                    propertyNo: p.row.propertyNo,
                    expectedVersion: p.row.version,
                  })),
                },
                rows: ready.map((p) => ({
                  propertyNo: p.row.propertyNo,
                  before: p.before,
                  offerCount: p.offerCount,
                })),
                nextLabel,
              })
            }

onOpenChange={(open) => {
          if (!open) setPending(null);
        }} | onConfirm={() => void submit()}

onClick={() => {
              if (t !== tab) {
                if (dirty) setNextTab(t);
                else choose(t);
              }
            }}

onChange={(e) =>
                        setShared((s) => ({
                          ...s,
                          [key]: ["saleable_area", "bedrooms", "bathrooms"].includes(key)
                            ? e.target.value === ""
                              ? null
                              : Number(e.target.value)
                            : e.target.value || (key === "title_zh" ? "" : null),
                        }))
                      }

onUploadingChange={setUploading} | onChange={(value) =>
                    setShared((s) => ({
                      ...s,
                      images: typeof value === "function" ? value(s.images) : value,
                    }))
                  }

onOpenChange={(open) => {
          if (!open) setPending(null);
        }} | onConfirm={() => {
