        }}

onOpenChange={setReloadConfirm} | onConfirm={() => {
          setBusy(true);
          void reload()
            .then(() => setReloadConfirm(false))
            .catch((e) => setError(e instanceof Error ? e.message : "載入失敗"))
            .finally(() => setBusy(false));
        }}

onChange={async (event) => {
            const file = event.target.files?.[0];
            event.target.value = "";
            if (!file) return;
            setUploading(true);
            uploadingChangeRef.current?.(true);
            setError(null);
            try {
              const result = await uploadAdminMedia(file, ownerType);
              if (active.current) changeRef.current(result.url);
            } catch (err) {
              if (active.current)
                setError(err instanceof Error ? err.message : "上載失敗，請重新選擇檔案重試。");
            } finally {
              if (active.current) {
                setUploading(false);
                uploadingChangeRef.current?.(false);
              }
            }
          }}

onClick={async () => {
          const local = JSON.stringify(localPayload, null, 2);
          setLoading(true);
          setError(false);
          try {
            const result = await fetchAdminCmsEditor({ data: { resourceType, resourceId } });
            setComparison({
              local,
              published: result.publishedPayload,
              version: result.editState?.currentPublishedVersion ?? null,
            });
          } catch {
            setError(true);
          } finally {
            setLoading(false);
          }
        }}

