              );
              setRetry((v) => v + 1);
            }}

onToggle={(no) =>
              setSelected((current) => {
                const next = new Set(current);
                if (next.has(no)) next.delete(no);
                else next.add(no);
                return next;
              })
            } | onToggleAll={() =>
              setSelected((current) => {
                const eligible = data.rows.filter(canSelectProperty).map((row) => row.propertyNo);
                return eligible.every((no) => current.has(no)) ? new Set() : new Set(eligible);
              })
            }

