                      status: detail.status,
                      assigned_agent_id: assignedAgentI

onEnquirySelect={(id) => {
            if (selectedId) setEnquirySelections((current) => ({ ...current, [selectedId]: id }));
          }} | onLoadOlder={loadOlderMessages} | onReplyBodyChange={setReplyBody} | onSendReply={sendReply} | onSendTemplate={sendTemplate} | onConsentSaved={() => {
            if (selectedIdRef.current) void loadConversationDetail(selectedIdRef.current);
          }} | onStatusChange={(status) =>
            detail
              ? saveConversationUpdate({
                  status,
                  assigned_agent_id: detail.assigned_agent_id,
                })
              : undefined
          } | onAgentChange={(assignedAgentId) =>
            detail
              ? saveConversationUpdate({
                  status: detail.status,
                  assigned_agent_id: assignedAgentId,
                })
              : undefined
          }

onUseSuggestedReply={(value) => {
              if (replyBody.trim() && !window.confirm("將會覆蓋你已輸入的回覆內容，確定繼續？")) {
                return;
              }
              onReplyBodyChange(value);
            }}

onScroll={() => {
        const e = container.current;
        if (e) pinned.current = e.scrollHeight - e.scrollTop - e.clientHeight < 80;
      }}

onValueChange={(value: SortOption) =>
          navigate({
            // Sorting keeps every other active filter as-is -- only the sort
            // column changes, plus the page resets since "page 2" means a
            // different set of rows once the ordering changes.
            search: (prev: Record<string, unknown>) => ({
              ...prev,
              sort: value,
              page: 1,
            }),
          })
        }

locator:
{
                          publicListingNo ? `想查詢編號 ${publicListingNo}` : "想查詢此樓盤"
                        }

baseline_handler:
onClick={() =>
                    updateSearch({ estate: undefined, category: undefined, q: undefined })
                  }

onClick={() => {
              setIsPlaying(true);
              track({ name: "video_click", payload: { videoId, category } }, buildContext());
            }}
